-- Completes operational tables requested for the controlled pilot.
begin;
create table if not exists public.locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),code text not null,name text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(laboratory_id,code));
create table if not exists public.equipment(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),location_id uuid references public.locations(id),code text not null,name text not null,serial_number text,status text not null default 'active' check(status in('active','maintenance','out_of_service','retired')),calibration_due date,created_at timestamptz not null default now(),unique(laboratory_id,code));
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),chapter_id smallint references public.chapters(id),title text not null,assigned_to uuid references public.profiles(id),status text not null default 'open' check(status in('open','in_progress','completed','cancelled')),due_date date,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.form_fields(id uuid primary key default gen_random_uuid(),template_version_id uuid not null references public.form_template_versions(id) on delete cascade,field_key text not null,label text not null,field_type text not null,required boolean not null default false,min_value numeric,max_value numeric,options jsonb,sort_order integer not null default 0,unique(template_version_id,field_key));
create table if not exists public.submission_values(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.form_submissions(id) on delete cascade,field_id uuid not null references public.form_fields(id),value_json jsonb not null,created_at timestamptz not null default now(),unique(submission_id,field_id));
create index if not exists equipment_scope_idx on public.equipment(organization_id,laboratory_id,status,calibration_due);create index if not exists tasks_scope_idx on public.tasks(organization_id,laboratory_id,status,due_date);create index if not exists form_fields_version_idx on public.form_fields(template_version_id,sort_order);create index if not exists submission_values_submission_idx on public.submission_values(submission_id);
alter table public.locations enable row level security;alter table public.equipment enable row level security;alter table public.tasks enable row level security;alter table public.form_fields enable row level security;alter table public.submission_values enable row level security;
do $$ begin
if not exists(select 1 from pg_policies where schemaname='public' and tablename='locations' and policyname='locations_read_scope')then create policy locations_read_scope on public.locations for select to authenticated using(public.can_read_scope(organization_id,laboratory_id));end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='equipment' and policyname='equipment_read_scope')then create policy equipment_read_scope on public.equipment for select to authenticated using(public.can_read_scope(organization_id,laboratory_id));end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='tasks' and policyname='tasks_read_scope')then create policy tasks_read_scope on public.tasks for select to authenticated using(public.can_read_scope(organization_id,laboratory_id));end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='form_fields' and policyname='form_fields_read_scope')then create policy form_fields_read_scope on public.form_fields for select to authenticated using(exists(select 1 from public.form_template_versions v join public.form_templates t on t.id=v.template_id where v.id=form_fields.template_version_id and public.can_read_scope(t.organization_id,t.laboratory_id)));end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='submission_values' and policyname='submission_values_read_scope')then create policy submission_values_read_scope on public.submission_values for select to authenticated using(exists(select 1 from public.form_submissions s where s.id=submission_values.submission_id and public.can_read_scope(s.organization_id,s.laboratory_id)));end if;
end $$;
commit;
